    product: productDoc,
    level: levelDoc,
    customer: req.body.customer
  };
  // Send order to fulfillment service
  //...
  res.json({ message: 'Order placed successfully' });
});

app.listen(3000, () => {
  console.log('Server started on port 3000');
});
