**GameCoinApp.swift**
```swift
import UIKit
import StoreKit

class GameCoinApp: UIViewController {
    // In-app coins
    var coins: Int = 100

    // In-app purchase product IDs
    let coinProductID = "com.example.gamecoinapp.coinpack"

    // UI elements
    @IBOutlet weak var coinLabel: UILabel!
    @IBOutlet weak var betLabel: UILabel!
    @IBOutlet weak var betButton: UIButton!
    @IBOutlet weak var resultLabel: UILabel!

    override func viewDidLoad() {
        super.viewDidLoad()
        // Initialize the UI
        coinLabel.text = "Coins: \(coins)"
        betLabel.text = "Bet: 0"
        betButton.setTitle("Bet", for:.normal)
    }

    // Handle in-app purchase
    func buyCoins() {
        let product = SKProduct(productID: coinProductID)
        let paymentQueue = SKPaymentQueue.default()
        paymentQueue.add(payment(product: product) { [weak self] (transaction) in
            if transaction.transactionState ==.failed {
                print("Purchase failed")
            } else {
                self?.coins += 100
                self?.coinLabel.text = "Coins: \(self?.coins?? 0)"
            }
        })
    }

    // Handle bet button tap
    @IBAction func betButtonTapped(_ sender: UIButton) {
        // Get the current bet amount
        let betAmount = Int(betLabel.text!)?? 0

        // Check if the user has enough coins
        if betAmount > coins {
            print("Not enough coins")
            return
        }

        // Simulate the game outcome
        let random = Int.random(in: 0...1)
        if random == 0 {
            // User wins
            coins += betAmount
            coinLabel.text = "Coins: \(coins)"
        } else {
            // User loses
            coins -= betAmount
            coinLabel.text = "Coins: \(coins)"
        }

